import React, { useState } from 'react';
import { ConfirmPopup } from 'primereact/confirmpopup';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="confirmPopup-accessibility">Accessible ConfirmPopup</label>
            <ConfirmPopup 
                id="confirmPopup-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible ConfirmPopup input"
                placeholder="Enter confirmPopup"
            />
        </div>
    );
}